        pulse(32'h00000017, 32'h000008BC);  // LOAD_AT  cell 0 <- gs=0x0BC 0x0BC GS_XOR (cfg=0x000008BC)
        pulse(32'h00000018, 32'h00000001);  // SET_TARGET cell 1
        pulse(32'h00000017, 32'h00000807);  // LOAD_AT  cell 1 <- gs=0x007 0x007 GS_AND (cfg=0x00000807)
        pulse(32'h00000018, 32'h00000002);  // SET_TARGET cell 2
        pulse(32'h00000017, 32'h00000824);  // LOAD_AT  cell 2 <- gs=0x024 0x024 GS_OR (cfg=0x00000824)
        chk(16'd0, 10'h0BC);
        chk(16'd1, 10'h007);
        chk(16'd2, 10'h024);
        if (fails==0) $display("  >>> PASS: all 3 programmed cells match");
        else $display("  >>> FAIL: %0d mismatch(es)", fails);
        $finish; end
endmodule
